import testCase from 'node:test';
import assert from 'node:assert/strict';
import {mkdirSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {translateProject} from '../project.mjs';
import {migrateCorePrimitives,proposeCorePrimitivesCorpus} from '../migrate-core-primitives.mjs';
import {migrateCoreFormatting} from '../migrate-core-formatting.mjs';
import {proposeCoreFormattingCorpus} from '../propose-core-formatting-corpus.mjs';
import {ROUTER_CORE_PRIMITIVES_SOURCE} from '../router-core-primitives.mjs';
import {ROUTER_FORMATTING_FACADE_SOURCE} from '../router-core-formatting.mjs';
import {transportConcreteSyntaxMeta} from '../concrete-syntax-meta.mjs';
import {parseProgram,serializeProgram} from '../semantic-meta.mjs';
import {sourceItems} from '../rust-structure.mjs';
import {verifyTypedTargets} from './typed-targets.mjs';

const directory=process.env.ROUTER_CORE_PRIMITIVES_MIGRATION_VECTOR_DIR;
let vectors=[];
const retain=(kind,value)=>{vectors.push({kind,value});return value;};
const digest=source=>createHash('sha256').update(source).digest('hex');
const test=(name,run)=>testCase(name,{timeout:60_000},async()=>{
  vectors=[];try{await run();}finally{if(directory){mkdirSync(directory,{recursive:true});writeFileSync(join(directory,Buffer.from(name).toString('hex')+'.json'),JSON.stringify({name,vectors},(_,value)=>typeof value==='bigint'?{$integer:String(value)}:value)+'\n');}}
});
const profile={flags:{test:false}},C='crate::translation_core::Str';
function migrate(source,options={}){return retain('complete-migration',migrateCorePrimitives(source,{compilationProfile:profile,...options}));}
function inverse(result){
  assert.equal(transportConcreteSyntaxMeta(result.before.meta).source,result.before.source);assert.equal(transportConcreteSyntaxMeta(result.after.meta).source,result.after.source);
  assert.equal(digest(result.before.source),result.before.sha256);assert.equal(digest(result.after.source),result.after.sha256);
  assert.deepEqual(result.trace.map(row=>row.phase),['language','repository']);assert.equal(result.executableAdmission,false);
  let old=0,next=0,reconstructed='';
  for(const row of result.mapping){assert.equal(row.before[0],old);assert.equal(row.after[0],next);const before=result.before.source.slice(...row.before),after=result.after.source.slice(...row.after);if(row.kind==='unchanged')assert.equal(before,after);else{assert.equal(before,row.expected);assert.equal(after,row.replacement);}reconstructed+=before;old=row.before[1];next=row.after[1];}
  assert.equal(old,result.before.source.length);assert.equal(next,result.after.source.length);assert.equal(reconstructed,result.before.source);
  let undo=result.after.source;for(const edit of [...result.mapping].reverse())if(edit.kind==='substitution')undo=undo.slice(0,edit.after[0])+edit.expected+undo.slice(edit.after[1]);assert.equal(undo,result.before.source);
}
function files(source){return {'src/lib.rs':'pub mod translation_core;\n'+source,'src/translation_core.rs':ROUTER_FORMATTING_FACADE_SOURCE,'src/translation_core/primitives.rs':ROUTER_CORE_PRIMITIVES_SOURCE};}
function project(source){const input=files(source);return retain('complete-new-project',translateProject({entry:'src/lib.rs',paths:Object.keys(input),readSource:path=>input[path],compilationProfile:profile}));}
const has=(result,name)=>result.meta.executable.some(item=>item.name===name);
function checked(result){const text=JSON.stringify(result.meta.checkedSemanticProgram),program=parseProgram(text);assert.equal(serializeProgram(program),text);retain('complete-checked-meta',text);return program;}
async function targets(result,verify){retain('complete-targets',{javascript:result.javascript,typescript:result.typescript});await verifyTypedTargets(result,verify,{childTimeoutMs:20_000});}
const some=field0=>({$:'Some',field0}),none={$:'None'};

// Complete pristine files, not hand-written lookalikes of the application.
// Their full bytes are checked independently before every actual-source case.
const ORIGINALS={"src/model_catalog_errors.rs":{"bytes":1361,"sha256":"286e433858cb1f3b4308c7b395a82ab05e4053f2699cea03c4e089f936fd469f","base64":""},"src/login_url.rs":{"bytes":11664,"sha256":"dd3f0762d4dbb77604be1ebad3cb8b6be5dc876a6aa03fd71304f5f99fdab783","base64":""},"src/token.rs":{"bytes":38509,"sha256":"7ca5ba2669621a395ddf9f9fbc3ce32c9c033be6fc8acea5b6ec264c233e53be","base64":""}};
function original(name){const row=ORIGINALS[name],source=Buffer.from(row.base64,'base64').toString('utf8');assert.equal(Buffer.byteLength(source),row.bytes);assert.equal(digest(source),row.sha256);retain('complete-original-'+name,{...row,source});return source;}

test('format-free signatures and direct constants adopt real borrowed-text semantics',async()=>{
  const source='const PREFIX:&str="prefix"; pub fn identity(value:&str)->&str{value} pub fn fixed()->&\'static str{PREFIX} pub fn cleaned(value:&str)->&str{value.trim()} pub fn bytes(value:&str)->usize{value.len()}';
  const result=migrate(source);inverse(result);assert.equal(result.edits.length,7);assert.equal(result.after.source.includes('format!'),false);
  assert.equal(result.after.source,'const PREFIX:&'+C+'="prefix"; pub fn identity(value:&'+C+')->&'+C+'{value} pub fn fixed()->&\'static '+C+'{PREFIX} pub fn cleaned(value:&'+C+')->&'+C+'{value.trim()} pub fn bytes(value:&'+C+')->usize{value.len()}');
  const output=project(result.after.source);for(const name of ['identity','fixed','cleaned','bytes'])assert.equal(has(output,name),true,name);
  const program=checked(output);assert.deepEqual(program.declarations.get('identity').params[0].type.rustOwnership,{kind:'borrowed',source:'str'});assert.equal(program.declarations.get('identity').sourceLifetimeProof.outputs[0].identity,'input:0:[]');assert.equal(program.declarations.get('fixed').ret.rustBorrowLifetime.kind,'static');
  await targets(output,api=>{for(const value of ['', 'Ω😀','a\0b'])assert.equal(api.identity(value),value);assert.equal(api.fixed(),'prefix');assert.equal(api.cleaned(' \tΩ😀\r\n'),'Ω😀');assert.equal(api.bytes('é😀'),6n);});
});

test('complete CST source keeps comments raw strings BOM CRLF and macro bodies unchanged',()=>{
  const source='\uFEFF// fn fake(v: &str)\r\nmacro_rules! untouched { ($x:tt)=>{ fn generated(v:&str)->&str{v} } }\r\nconst NOTE:&str=r##"&str Ω { }"##;\r\npub fn real(value: &str) -> &str { let body: &str="&str"; value }\r\n';
  const result=migrate(source);inverse(result);assert.equal(result.edits.length,3);
  assert.ok(result.after.source.includes('fn generated(v:&str)->&str{v}'));assert.ok(result.after.source.includes('let body: &str="&str"'));assert.ok(result.after.source.includes('r##"&str Ω { }"##'));assert.ok(result.after.source.startsWith('\uFEFF// fn fake(v: &str)\r\n'));
  for(const edit of result.edits){assert.equal(source.slice(...edit.span),'str');assert.equal(edit.replacement,C);}
});

test('structural nested types and real declaration owners avoid body and pattern false rewrites',()=>{
  const source='const SLICES:&[&str;2]=&["a","b"]; fn f((a,b):(&str,&str),value:Option<&str>)->Option<&str>{let local:&str=a;value} mod nested { pub fn echo(v:&str)->&str{v} } struct Owner; impl Owner { fn echo(&self,v:&str)->&str{v} } struct Field { text:&\'static str }';
  const result=migrate(source);inverse(result);assert.equal(result.edits.length,9);assert.ok(result.after.source.includes('const SLICES:&[&'+C+';2]'));assert.ok(result.after.source.includes('value:Option<&'+C+'>)->Option<&'+C+'>'));
  assert.ok(result.after.source.includes('let local:&str=a'));assert.ok(result.after.source.includes('struct Field { text:&\'static str }'));
  assert.ok(result.selections.some(row=>row.path.includes('nested')&&row.name==='echo'));assert.ok(result.selections.some(row=>row.path.includes('impl Owner')&&row.name==='echo'));
  const uncertain='fn generic<T>(v:&str)->&str{v} fn pointer(v:fn(&str)->&str)->u8{0} impl<T> Owner<T>{fn method(v:&str)->&str{v}}';
  const kept=migrate(uncertain);inverse(kept);assert.equal(kept.after.source,uncertain);assert.equal(kept.edits.length,0);assert.ok(kept.skipped.length>=3);
});

test('named lifetimes mutable raw and qualified types keep bounded refusal or idempotent source',()=>{
  const sources=["fn f<'a>(v:&'a str)->&'a str{v}","fn f(v:&'_ str)->u8{0}","fn f(v:&'elided str)->u8{0}",'fn f(v:&mut str)->u8{0}','fn f(v:&r#str)->u8{0}','fn f(v:&std::primitive::str)->u8{0}','fn f(v:&Alias)->u8{0}','trait Trait { fn method(v:&str)->&str; } struct Owner; impl Trait for Owner { fn method(v:&str)->&str{v} }','impl dyn Owner { fn method(v:&str)->&str{v} }','impl Owner Other { fn method(v:&str)->&str{v} }',`fn f(v:&${C})->&${C}{v}`];
  for(const source of sources){const result=migrate(source);inverse(result);assert.equal(result.after.source,source);assert.equal(result.edits.length,0);}
  const stable=migrate("const V:&'static str=\"x\"; fn f(v:&'static str)->&'static str{v}");inverse(stable);assert.equal(stable.edits.length,3);
  const second=migrate(stable.after.source);inverse(second);assert.equal(second.edits.length,0);assert.equal(second.after.source,stable.after.source);
});

test('competing imports declarations and unknown producers retain complete scope skips',()=>{
  const body='pub fn f(v:&str)->&str{v}';
  for(const prefix of ['type str=String;','use custom::str;','use custom::Thing as str;','use custom::*;','#[custom] struct S;','#[derive(Custom)] struct S;','produce!{struct str;}','extern crate custom as str;','pub extern crate str;','extern "C" { type str; }','declaration_without_known_role;']){
    const result=migrate(prefix+body);inverse(result);assert.equal(result.edits.length,0,prefix);assert.ok(result.skipped.some(row=>row.blockers?.length),prefix);
  }
  const selfAlias=migrate('extern crate self as link_assistant_router;'+body);inverse(selfAlias);assert.equal(selfAlias.edits.length,2);assert.ok(selfAlias.after.source.startsWith('extern crate self as link_assistant_router;'));
  const root=migrate(body,{rootSource:'use custom::*;'});assert.equal(root.edits.length,0);
  const source='pub fn outer(v:&str)->&str{v} mod shadow {use custom::str; pub fn inner(v:&str)->&str{v}} #[cfg(test)] mod tests {use super::*; fn test(v:&str){}}';
  const result=migrate(source);inverse(result);assert.equal(result.edits.length,2);assert.ok(result.after.source.includes('pub fn inner(v:&str)->&str{v}'));assert.ok(result.skipped.some(row=>row.reason==='module configuration inactive'));
  let callbacks=0;const getter=Object.defineProperty({},'src/lib.rs',{enumerable:true,get(){callbacks++;return body;}}),proxy=new Proxy({},{get(){callbacks++;return body;},ownKeys(){callbacks++;return [];},getPrototypeOf(){callbacks++;return Object.prototype;}});
  for(const input of [getter,proxy])assert.throws(()=>proposeCorePrimitivesCorpus({files:input}),TypeError);assert.equal(callbacks,0);
});

test('actual complete caller files retain all producer and downstream semantic refusals',()=>{
  const actual={model:original('src/model_catalog_errors.rs'),login:original('src/login_url.rs'),token:original('src/token.rs')};
  const input={'src/lib.rs':'pub mod translation_core; pub mod model_catalog_errors; pub mod login_url; pub mod token;','src/translation_core.rs':ROUTER_FORMATTING_FACADE_SOURCE,'src/translation_core/primitives.rs':ROUTER_CORE_PRIMITIVES_SOURCE,'src/model_catalog_errors.rs':actual.model,'src/login_url.rs':actual.login,'src/token.rs':actual.token};
  const result=retain('full-actual-corpus-proposal',proposeCorePrimitivesCorpus({files:input,compilationProfile:profile}));
  for(const row of result.proposals)inverse(row);
  const model=result.proposals.find(row=>row.file==='src/model_catalog_errors.rs'),login=result.proposals.find(row=>row.file==='src/login_url.rs'),token=result.proposals.find(row=>row.file==='src/token.rs');
  assert.deepEqual(model.selections.filter(row=>row.kind==='fn'&&row.edits.length).map(row=>row.name),['resource_error_code','is_permission_refusal','is_credential_rejection']);
  for(const name of ['unwrap_terminal_lines','extract_login_url','extract_token','redact_secrets','redact_prefix','secret_run_len','redact_value','trim_url_punctuation'])assert.ok(login.selections.some(row=>row.name===name&&row.edits.length),name);
  // Unknown serde derive effects are retained; this source-only tool does not
  // invent their outward type confinement just to rewrite these constants.
  assert.equal(token.edits.length,0);assert.equal(result.after['src/token.rs'],actual.token);assert.ok(token.skipped.some(row=>row.name==='TOKEN_PREFIX'&&row.blockers.some(block=>block.reason.includes('derive'))));
  assert.equal(result.executableAdmission,false);assert.equal(result.moduleGraph.modules.some(module=>module.file==='src/login_url.rs'),true);
  const build=all=>translateProject({entry:'src/lib.rs',paths:Object.keys(all),readSource:path=>all[path],compilationProfile:profile});
  const before=retain('complete-original-caller-project',build(result.before)),after=retain('complete-adopted-caller-project',build(result.after));
  assert.equal(before.meta.runtimeParity,false);assert.equal(after.meta.runtimeParity,false);assert.ok(after.meta.refused.length>0);
  retain('remaining-complete-refusal-comparison',{before:before.meta.refused,after:after.meta.refused});
});

test('actual token constant and callback bodies use the same rule in a closed caller',async()=>{
  const source=original('src/token.rs'),items=sourceItems(source),names=['TOKEN_PREFIX','CODEX_TOKEN_PREFIX','token_jwt'];
  const declarations=names.map(name=>{const item=items.find(item=>item.name===name);assert.ok(item,name);return source.slice(item.start,item.end);});
  const actual=declarations.join('\n'),migration=migrate(actual);inverse(migration);assert.equal(migration.edits.length,4);
  const result=project(migration.after.source);assert.equal(has(result,'token_jwt'),true);checked(result);
  const expected=[['la_sk_abc',some('abc')],['at-abc',some('abc')],['la_sk_',some('')],['at-',some('')],['other',none],['',none],['la_sk_Ω😀',some('Ω😀')]];retain('independent-token-prefix-expected',expected);
  await targets(result,api=>{for(const [value,wanted]of expected)assert.deepEqual(api.token_jwt(value),wanted);});
  retain('scope-distinction','Complete source case retains serde-producer refusal. This closed actual-declaration case tests unchanged original body behavior, not full token module admission or an application coverage gain.');
});

test('formatting composition and repeated corpus proposals keep fresh complete source associations',()=>{
  const source='pub fn echo(v:&str)->String{format!("{}",v)} pub fn unchanged(v:&str)->&str{v}';
  const formatting=retain('complete-first-formatting-proposal',migrateCoreFormatting(source));
  const migration=migrate(formatting.after.source);inverse(migration);assert.equal(migration.edits.length,2);assert.ok(migration.after.source.includes('crate::translation_core::format!'));assert.ok(migration.after.source.includes('v:&'+C+')->&'+C+'{v}'));
  const first=retain('complete-314-formatting-corpus',proposeCoreFormattingCorpus({files:files(source),compilationProfile:profile}));
  const composed=Object.fromEntries(first.inputs.map(row=>[row.path,row.source]));for(const row of first.rows)if(row.status==='proposed')composed[row.path]=row.proposal.after.source;
  const corpus=proposeCorePrimitivesCorpus({files:composed,compilationProfile:profile});retain('complete-composed-corpus',corpus);assert.equal(corpus.after['src/lib.rs'],'pub mod translation_core;\n'+migration.after.source);
  const second=proposeCorePrimitivesCorpus({files:corpus.after,compilationProfile:profile});retain('complete-second-corpus',second);assert.deepEqual(second.after,corpus.after);assert.equal(second.proposals.flatMap(row=>row.edits).length,0);
  const alias=proposeCorePrimitivesCorpus({files:{...files(''),'src/lib.rs':'pub mod translation_core; mod one; #[path="one.rs"] mod two;','src/one.rs':'pub fn f(v:&str)->&str{v}'},compilationProfile:profile});retain('complete-alias-refusal',alias);assert.equal(alias.after['src/one.rs'],alias.before['src/one.rs']);assert.ok(alias.skipped.some(row=>row.file==='src/one.rs'&&row.reason.includes('multiple')));
  assert.throws(()=>proposeCorePrimitivesCorpus({files:corpus}),TypeError);
});
